class BaseClass:
    def __init__(
        self,
        corpid: str,
        token: str,
        aeskey: str,
    ) -> None:
        self.id = corpid
        self.token = token
        self.key = aeskey
        self.sha = hashlib.sha1()
        self.mode = AES.MODE_CBC
        self.block_size = 32
        self.aes_text_response_template = """
            <xml>
            <Encrypt><![CDATA[%(msg_encrypt)s]]></Encrypt>
            <MsgSignature><![CDATA[%(msg_signaturet)s]]></MsgSignature>
            <TimeStamp>%(timestamp)s</TimeStamp>
            <Nonce><![CDATA[%(nonce)s]]></Nonce>
            </xml>
        """

    @property
    @WeLog
    def aes_key_with_base64(self):

        key = base64.b64decode(self.key + "=")
        try:
            assert len(key) == 32
        except AssertionError:
            raise CustomException(
                base64_aeskey_error, f"base64 aeskey error: {self.key}"
            )
        return key

    @WeLog
    def delete_random(self, text: bytes):
        sl = []
        try:
            last_pad = text[-1]
            content = text[16:-last_pad]
            xml_len = socket.ntohl(struct.unpack("I", content[:4])[0])
            sl.append(content)
            sl.append(xml_len)
            return sl
        except Exception:
            raise CustomException(delete_random_error, f"delete random error: {text}")

    @WeLog
    def extract_read_xml(self, text: bytes) -> bytes:
        sl = self.delete_random(text)
        xml_content = sl[0][4 : sl[1] + 4]
        return xml_content

    @WeLog
    def extract_corp_id(self, text: bytes) -> str:
        sl = self.delete_random(text)
        corpid = sl[0][sl[1] + 4 :]
        return corpid.decode("utf8")

    @WeLog
    def extract_request_body(self, data: bytes):
        try:
            xml_tree = ET.fromstring(data)
            encrypt = xml_tree.find("Encrypt")
        except Exception:
            raise CustomException(
                extract_request_body_error, f"extract request body error: {data}"
            )
        return encrypt.text

    @WeLog
    def reply_assemble_body(
        self, xml_content: str, signature: str, timestamp: str, nonce: str
    ) -> str:
        resp_dict = {
            "msg_encrypt": xml_content,
            "msg_signaturet": signature,
            "timestamp": timestamp,
            "nonce": nonce,
        }
        resp_xml = self.aes_text_response_template % resp_dict
        return resp_xml


class DecryptionClass(BaseClass):
    def __init__(self, corpid: str, token: str, aeskey: str) -> None:
        super().__init__(corpid, token, aeskey)

    @WeLog
    def decrypt_echostr(self, echostr: str) -> bytes:
        try:
            base64Key = super().aes_key_with_base64
            crypt = AES.new(base64Key, self.mode, base64Key[:16])
            xml_bytes = crypt.decrypt(base64.b64decode(echostr))
            return xml_bytes
        except Exception:
            raise CustomException(
                decrypt_echostr_error, f"decrypt echostr error: {echostr}"
            )


class EncryptionClass(BaseClass):
    def __init__(self, corpid: str, token: str, aeskey: str) -> None:
        super().__init__(corpid, token, aeskey)

    @property
    @WeLog
    def random_str(self):
        return str(random.randint(1000000000000000, 9999999999999999)).encode()

    @WeLog
    def encrypt_request_signature(self, timestamp: str, nonce: str, encrypt: str):
        ttne = [self.token, timestamp, nonce, encrypt]
        ttne.sort()
        try:
            self.sha.update("".join(ttne).encode())
            return self.sha.hexdigest()
        except Exception:
            raise CustomException(
                encrypt_request_signature_error,
                f"encrypt request signature error: {ttne}",
            )

    @WeLog
    def encrypt_reply_msg(self, rspBody: str):
        base64Key = super().aes_key_with_base64
        rsp_content = rspBody.encode()
        xml_content = (
            self.random_str
            + struct.pack("I", socket.htonl(len(rsp_content)))
            + rsp_content
            + self.id.encode()
        )
        text_length_length = len(xml_content)
        amount_to_pad = self.block_size - (text_length_length % self.block_size)
        if amount_to_pad == 0:
            amount_to_pad = self.block_size
        pad = chr(amount_to_pad)
        xml_content = xml_content + (pad * amount_to_pad).encode()
        cryptos = AES.new(base64Key, self.mode, base64Key[:16])
        try:
            ciphertext = cryptos.encrypt(xml_content)
            return base64.b64encode(ciphertext)
        except Exception:
            raise CustomException(
                encrypt_reply_msg_error, f"encrypt reply msg error: {xml_content}"
            )


class SignCallback:
    def __init__(
        self,
        config: Config,
        signature: str,
        timestamp: str,
        nonce: str,
        echo: str,
    ):
        self.corp_id = config.qywx.corpid
        self.token = config.qywx.openapi.token
        self.aeskey = config.qywx.openapi.aeskey
        self.signature = signature
        self.timestamp = timestamp
        self.nonce = nonce
        self.echostr = echo
        self.dtc = DecryptionClass(self.corp_id, self.token, self.aeskey)
        self.etc = EncryptionClass(self.corp_id, self.token, self.aeskey)

    @property
    @WeLog
    def verify_signature(self) -> bool:
        signature = self.etc.encrypt_request_signature(
            self.timestamp, self.nonce, self.echostr
        )
        if self.signature == signature:
            return True
        return False

    @property
    @WeLog
    def verify_corpid(self) -> bytes:
        xml_bytes = self.dtc.decrypt_echostr(self.echostr)
        corpid = self.dtc.extract_corp_id(xml_bytes)
        if self.corp_id != corpid:
            raise CustomException(
                corp_invalid_error,
                (
                    f"decrypt corp_id is {corpid}, config corp_id is {self.corp_id}, "
                    f"verify failed, please check the corp_id is valid"
                ),
            )

        xml_text = self.dtc.extract_read_xml(xml_bytes)

        return xml_text


class ReplyMsg:
    def __init__(self, config: Config):
        self.corp_id = config.qywx.corpid
        self.token = config.qywx.openapi.token
        self.aeskey = config.qywx.openapi.aeskey
        self.timestamp = str(int(time.time()))
        self.etc = EncryptionClass(self.corp_id, self.token, self.aeskey)

    @WeLog
    def reply_encrypt(self, reply_xml: str) -> bytes:
        replyBytes = self.etc.encrypt_reply_msg(reply_xml)
        return replyBytes

    @WeLog
    def reply_signature(self, nonce: str, body: bytes) -> str:
        replySignature = self.etc.encrypt_request_signature(self.timestamp, nonce, body)
        return replySignature

    @WeLog
    def reply_body(self, body: bytes, signature: str, nonce: str) -> bytes:
        reply = self.etc.reply_assemble_body(body, signature, self.timestamp, nonce)
        return reply


class CallbackEvent:
    def __init__(
        self, config: Config, signature: str, timestamp: str, nonce: str, body: bytes
    ):
        self.config = config
        self.corp_id = config.qywx.corpid
        self.token = config.qywx.openapi.token
        self.aeskey = config.qywx.openapi.aeskey
        self.signature = signature
        self.timestamp = timestamp
        self.nonce = nonce
        self._body = body
        self.dtc = DecryptionClass(self.corp_id, self.token, self.aeskey)
        self.etc = EncryptionClass(self.corp_id, self.token, self.aeskey)

    @WeLog
    def body(self) -> bytes:
        return self.dtc.extract_request_body(self._body)

    @property
    @WeLog
    def verify_corpid(self) -> bytes:
        body = self.body()
        xml_bytes = self.dtc.decrypt_echostr(body)
        corpid = self.dtc.extract_corp_id(xml_bytes)
        if self.corp_id != corpid:
            raise CustomException(
                corp_invalid_error,
                (
                    f"decrypt corp_id is {corpid}, config corp_id is {self.corp_id}, "
                    f"verify failed, please check the corp_id is valid"
                ),
            )
        return xml_bytes

    @property
    @WeLog
    def reply_msg(self) -> ET.ElementTree:
        xml_text = self.dtc.extract_read_xml(self.verify_corpid)
        xml_tree = ET.fromstring(xml_text)
        return xml_tree

    @property
    @WeLog
    def reply_content(self) -> str:
        xml_tree = self.reply_msg

        to_user_name, from_user_name, create_time_text = (
            getattr(xml_tree.find("ToUserName"), "text", ""),
            getattr(xml_tree.find("FromUserName"), "text", ""),
            getattr(xml_tree.find("CreateTime"), "text", ""),
        )

        # if msg_type is not text or event, return text
        msg_type_text = getattr(xml_tree.find("MsgType"), "text", "text")

        if msg_type_text == "text":
            return self._reply_text(
                to_user_name,
                from_user_name,
                create_time_text,
                getattr(
                    xml_tree.find("Content"),
                    "text",
                    "your reply is empty, this is a text",
                ),
            )

        elif msg_type_text == "event":
            # get user select option
            event_text = getattr(xml_tree.find("Event"), "text", "")
            if event_text == "template_card_event":
                event_key_text = getattr(xml_tree.find("EventKey"), "text", "")
                response_code = getattr(xml_tree.find("ResponseCode"), "text", "")
                selected_map = {}
                if (selected_items := xml_tree.find("SelectedItems")) is not None:
                    for item in selected_items.findall("SelectedItem"):
                        question_key_text = getattr(
                            item.find("QuestionKey"), "text", ""
                        )
                        if (
                            question_key_text
                            and (opts := item.find("OptionIds")) is not None
                        ):
                            for opt in opts.findall("OptionId"):
                                if opt.text:
                                    selected_map[question_key_text] = opt.text
                                    break

                return self._dispatch_card(
                    to_user_name,
                    from_user_name,
                    create_time_text,
                    event_key_text,
                    selected_map,
                    response_code,
                )

        return self._reply_text(
            to_user_name,
            from_user_name,
            create_time_text,
            f"unsupported event type: {msg_type_text}, only support text or template_card_event event",
        )

